/* ------------------------------------------------------------------ */
/*  Onboarding                                                          */
/* ------------------------------------------------------------------ */

function OnboardingScreen({ onCreate, lang = "uk", cityControl }) {
  const tgUser = getTelegramUser();
  const defaultName = tgUser?.first_name || tgUser?.username || "";
  const [username, setUsername] = useState(defaultName);
  const [selected, setSelected] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [pickerOpen, setPickerOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [blockedMsg, setBlockedMsg] = useState("");

  const canSubmit = username.trim().length > 0 && selected && !submitting;
  const selectedCountry = selected ? COUNTRY_MAP[selected] : null;

  const filteredCountries = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return COUNTRIES;
    return COUNTRIES.filter(
      (c) => c.name.toLowerCase().includes(q) || c.code.toLowerCase().includes(q)
    );
  }, [query]);

  const handleSubmit = async () => {
    if (!canSubmit) return;
    if (isCountryFullyConquered(selected, cityControl)) {
      setBlockedMsg("Цю країну повністю захоплено — оберіть іншу.");
      setSelected(null);
      return;
    }
    setSubmitting(true);
    await onCreate(username, selected);
  };

  const togglePicker = () => {
    setPickerOpen((open) => !open);
  };

  const pickCountry = (code) => {
    if (isCountryFullyConquered(code, cityControl)) return;
    setBlockedMsg("");
    setSelected(code);
    setPickerOpen(false);
    setQuery("");
  };

  return (
    <div className="cn-onboard">
      <div className="cn-onboard-header">
        <Globe2 size={40} className="cn-onboard-icon" />
        <div className="cn-onboard-title">WORLD CLICKER</div>
        <div className="cn-onboard-sub">{t(lang, "onboard_sub")}</div>
      </div>

      <div className="cn-field">
        <label className="cn-label">{t(lang, "onboard_name_label")}</label>
        <div className="cn-input-icon-wrap">
          <User size={18} className="cn-input-icon" />
          <input
            className="cn-input cn-input--icon"
            maxLength={20}
            placeholder={t(lang, "onboard_name_placeholder")}
            value={username}
            onChange={(e) => setUsername(e.target.value)}
          />
        </div>
      </div>

      <div className="cn-field cn-field--picker">
        <label className="cn-label">{t(lang, "onboard_country_label")}</label>
        <button type="button" className="cn-country-select" onClick={togglePicker}>
          {selectedCountry ? (
            <span className="cn-country-select-value">
              <Flag code={selectedCountry.code} size={18} className="cn-country-select-flag" />
              {selectedCountry.name}
            </span>
          ) : (
            <span className="cn-country-select-value cn-country-select-placeholder">
              <Globe2 size={18} className="cn-select-icon" />
              {t(lang, "onboard_country_choose")}
            </span>
          )}
          <ChevronDown size={18} className={"cn-chevron" + (pickerOpen ? " cn-chevron--open" : "")} />
        </button>

        {pickerOpen && (
          <>
            <div className="cn-picker-overlay" onClick={() => setPickerOpen(false)} />
            <div className="cn-country-dropdown">
              <div className="cn-country-search-wrap">
                <Search size={15} className="cn-country-search-icon" />
                <input
                  className="cn-country-search"
                  placeholder={t(lang, "onboard_country_search")}
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  autoFocus
                />
              </div>
              <div className="cn-country-dropdown-list">
                {filteredCountries.length === 0 && (
                  <div className="cn-country-dropdown-empty">{t(lang, "onboard_country_empty")}</div>
                )}
                {filteredCountries.map((c) => {
                  const conquered = isCountryFullyConquered(c.code, cityControl);
                  return (
                    <button
                      key={c.code}
                      type="button"
                      disabled={conquered}
                      className={
                        "cn-country-dropdown-item" +
                        (selected === c.code ? " cn-country-dropdown-item--active" : "") +
                        (conquered ? " cn-country-dropdown-item--disabled" : "")
                      }
                      onClick={() => pickCountry(c.code)}
                    >
                      <Flag code={c.code} size={18} className="cn-country-dropdown-flag" />
                      <span className="cn-country-dropdown-name">
                        {c.name}
                        {conquered && " — повністю захоплена"}
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          </>
        )}
        {blockedMsg && <div className="cn-onboard-blocked-msg">{blockedMsg}</div>}
      </div>

      <button className="cn-primary-btn" disabled={!canSubmit} onClick={handleSubmit}>
        <span className="cn-primary-btn-emoji">🏆</span>
        <span className="cn-primary-btn-label">{submitting ? t(lang, "onboard_creating_btn") : t(lang, "onboard_start_btn")}</span>
        <ChevronRight size={20} className="cn-primary-btn-chevron" />
      </button>
      <div className="cn-onboard-note">
        <Shield size={13} className="cn-onboard-note-icon" />
        {t(lang, "onboard_lock_note")}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Clicker screen                                                      */
/* ------------------------------------------------------------------ */

function ClickerScreen({
  player,
  onClick,
  wars,
  rebellions,
  alliances,
  cityControl,
  cityDefense,
  isLeader,
  isAdvisor,
  news,
  players,
  onSetPlayer,
  onRefreshGameData,
  helpAllyWarId,
  onToggleHelpAllyWar,
}) {
  const country = COUNTRY_MAP[player.countryCode];
  const [effects, setEffects] = useState([]);
  const [pressed, setPressed] = useState(false);
  const [shake, setShake] = useState(false);
  const [newsOpen, setNewsOpen] = useState(false);
  const [rewardsOpen, setRewardsOpen] = useState(false);
  const [panelOpen, setPanelOpen] = useState(false);
  const globeRef = useRef(null);
  const lastEffectTsRef = useRef(0);
  const MAX_EFFECTS = 6;

  /* Local energy tick - scoped to this screen only, so other tabs
     (Map, Profile, etc.) don't re-render every second for no reason. */
  const [, localTick] = useState(0);
  useEffect(() => {
    const t = setInterval(() => localTick((x) => x + 1), 1000);
    return () => clearInterval(t);
  }, []);
  const energy = getCurrentEnergy(player);

  /* ---- Автоклікер: доступний лише власникам Premium Pass, максимум
     половину доби (12 годин) активної роботи на добу. ---- */
  const autoSaveTimerRef = useRef(null);
  const persistPlayerSoon = useCallback((record) => {
    if (autoSaveTimerRef.current) clearTimeout(autoSaveTimerRef.current);
    autoSaveTimerRef.current = setTimeout(() => {
      storageSet(PLAYER_PREFIX + record.id, JSON.stringify(record), true);
    }, 1200);
  }, []);

  const todayKeyStr = new Date().toISOString().slice(0, 10);
  const autoClickerUsedToday = player.autoClickerDate === todayKeyStr ? player.autoClickerUsedMs || 0 : 0;
  const autoClickerRemainingMs = Math.max(0, AUTO_CLICKER_DAILY_LIMIT_MS - autoClickerUsedToday);
  const autoClickerActive = !!player.hasPremiumPass && !!player.autoClickerOn && autoClickerRemainingMs > 0;

  const toggleAutoClicker = useCallback(() => {
    if (!player.hasPremiumPass) return;
    onSetPlayer((prev) => {
      if (!prev) return prev;
      const t = new Date().toISOString().slice(0, 10);
      const usedToday = prev.autoClickerDate === t ? prev.autoClickerUsedMs || 0 : 0;
      if (!prev.autoClickerOn && usedToday >= AUTO_CLICKER_DAILY_LIMIT_MS) return prev;
      const updated = { ...prev, autoClickerOn: !prev.autoClickerOn, autoClickerDate: t, autoClickerUsedMs: usedToday };
      persistPlayerSoon(updated);
      return updated;
    });
  }, [player.hasPremiumPass, onSetPlayer, persistPlayerSoon]);

  useEffect(() => {
    if (!autoClickerActive || energy < 1) return;
    const timer = setTimeout(() => {
      onClick();
      onSetPlayer((prev) => {
        if (!prev) return prev;
        const t = new Date().toISOString().slice(0, 10);
        const usedToday = (prev.autoClickerDate === t ? prev.autoClickerUsedMs || 0 : 0) + AUTO_CLICKER_TICK_MS;
        const stillOn = prev.autoClickerOn && usedToday < AUTO_CLICKER_DAILY_LIMIT_MS;
        const updated = { ...prev, autoClickerDate: t, autoClickerUsedMs: usedToday, autoClickerOn: stillOn };
        persistPlayerSoon(updated);
        return updated;
      });
    }, AUTO_CLICKER_TICK_MS);
    return () => clearTimeout(timer);
  }, [autoClickerActive, energy, onClick, onSetPlayer, persistPlayerSoon]);

  const spawnEffects = useCallback((clientX, clientY, allowed) => {
    if (!allowed) {
      setShake(true);
      cnSfx.error();
      setTimeout(() => setShake(false), 350);
      return;
    }
    /* Every click always earns Power immediately (handled by the caller).
       The ripple/+1 animation is a visual flourish only, so during very
       fast clicking we throttle *just this* and cap how many are alive
       at once, to avoid piling up DOM nodes/animations and causing jank. */
    const now = Date.now();
    if (now - lastEffectTsRef.current < 35) return;
    lastEffectTsRef.current = now;

    const rect = globeRef.current?.getBoundingClientRect();
    const x = rect ? clientX - rect.left : 0;
    const y = rect ? clientY - rect.top : 0;
    const id = now + Math.random();
    setEffects((prev) => {
      const next = [...prev, { id, x, y }];
      return next.length > MAX_EFFECTS ? next.slice(next.length - MAX_EFFECTS) : next;
    });
    setTimeout(() => setEffects((prev) => prev.filter((i) => i.id !== id)), 700);
  }, []);

  const handlePress = (e) => {
    const clientX = e.clientX ?? 0;
    const clientY = e.clientY ?? 0;
    setPressed(true);
    setTimeout(() => setPressed(false), 120);
    cnSfx.tap();
    onClick((allowed) => spawnEffects(clientX, clientY, allowed));
  };

  const energyPct = Math.max(0, Math.min(100, (energy / MAX_ENERGY) * 100));
  const isEmpty = energy < 1;
  const unreadNews = news && news.length > 0;

  const myWar = (wars || []).find(
    (w) =>
      w.status !== "ended" &&
      (w.attackerCountry === player.countryCode ||
        w.defenderCountry === player.countryCode ||
        (w.attackerAllies || []).includes(player.countryCode) ||
        (w.defenderAllies || []).includes(player.countryCode))
  );
  const myIsAttackerSide =
    myWar &&
    (myWar.attackerCountry === player.countryCode || (myWar.attackerAllies || []).includes(player.countryCode));

  /* War of an ALLY country (not my own) - shown only when I'm not
     already personally fighting. Purely opt-in: tapping the banner
     toggles whether my clicks go to the ally's side or stay mine. */
  const allyWar = !myWar ? findAllyWar(wars, alliances, player.countryCode) : null;
  const isHelpingAllyWar = !!(allyWar && helpAllyWarId === allyWar.id);
  const allySideIsAttacker = allyWar && getAllyCountries(alliances, player.countryCode).includes(allyWar.attackerCountry);
  const allyCountryCode = allyWar ? (allySideIsAttacker ? allyWar.attackerCountry : allyWar.defenderCountry) : null;

  return (
    <div className="cn-clicker">
      <div className="cn-clicker-topbar">
        <span className="cn-country-pill">
          <Flag code={country?.code} size={16} /> {country?.name}
        </span>
        <div className="cn-clicker-top-actions">
          <button className="cn-icon-tile" type="button" onClick={() => { cnSfx.modalOpen(); setNewsOpen(true); }} aria-label="Новини">
            <Newspaper size={19} />
            {unreadNews && <span className="cn-icon-btn-dot" />}
          </button>
          <button className="cn-icon-tile" type="button" onClick={() => { cnSfx.modalOpen(); setRewardsOpen(true); }} aria-label="Щоденні нагороди">
            <Gift size={19} />
            <span className="cn-icon-btn-dot" />
          </button>
        </div>
      </div>

      {myWar && (
        <div className="cn-clicker-war-banner">
          <div className="cn-war-banner-row">
            <span className="cn-war-side">
              <Flag code={myWar.attackerCountry} size={16} /> {COUNTRY_MAP[myWar.attackerCountry]?.name}
            </span>
            <Swords size={15} className="cn-war-vs-icon" />
            <span className="cn-war-side">
              <Flag code={myWar.defenderCountry} size={16} /> {COUNTRY_MAP[myWar.defenderCountry]?.name}
            </span>
          </div>
          {myWar.status === "prep" ? (
            <>
              <div className="cn-war-city">
                Підготовка до битви за {myWar.city}: {Math.max(0, Math.ceil((myWar.prepEndsAt - Date.now()) / 1000))} с
              </div>
              <div className="cn-control-hint" style={{ textAlign: "center", marginTop: 4 }}>
                Коли почнеться битва, твої кліки почнуть іти прямо на {myIsAttackerSide ? "напад" : "захист"} замість особистого Power
              </div>
            </>
          ) : (
            <>
              <div className="cn-war-city">
                Битва за {myWar.city} — твої кліки йдуть на {myIsAttackerSide ? "напад" : "захист"}!
              </div>
              <div className="cn-war-power-row" style={{ marginTop: 8 }}>
                <span>{fmt(myWar.attackerPower || 0)}</span>
                <div className="cn-war-power-bar">
                  <div
                    className="cn-war-power-fill cn-war-power-fill--attacker"
                    style={{
                      width: ((myWar.attackerPower || 0) / Math.max(1, (myWar.attackerPower || 0) + (myWar.defenderPower || 0))) * 100 + "%",
                    }}
                  />
                </div>
                <span>{fmt(myWar.defenderPower || 0)}</span>
              </div>
            </>
          )}
        </div>
      )}

      {allyWar && (
        <div
          className={
            "cn-clicker-war-banner cn-clicker-ally-war-banner" +
            (isHelpingAllyWar ? " cn-clicker-ally-war-banner--helping" : "")
          }
          onClick={() => onToggleHelpAllyWar(isHelpingAllyWar ? null : allyWar.id)}
          role="button"
          tabIndex={0}
        >
          <div className="cn-war-banner-row">
            <span className="cn-war-side">
              <Flag code={allyWar.attackerCountry} size={16} /> {COUNTRY_MAP[allyWar.attackerCountry]?.name}
            </span>
            <Swords size={15} className="cn-war-vs-icon" />
            <span className="cn-war-side">
              <Flag code={allyWar.defenderCountry} size={16} /> {COUNTRY_MAP[allyWar.defenderCountry]?.name}
            </span>
          </div>
          <div className="cn-war-city">
            <Flag code={allyCountryCode} size={12} /> Твій союзник {COUNTRY_MAP[allyCountryCode]?.name} у війні за {allyWar.city}
          </div>
          {allyWar.status === "prep" ? (
            <div className="cn-control-hint" style={{ textAlign: "center", marginTop: 4 }}>
              Підготовка до битви: {Math.max(0, Math.ceil((allyWar.prepEndsAt - Date.now()) / 1000))} с
            </div>
          ) : (
            <>
              <div className="cn-control-hint" style={{ textAlign: "center", marginTop: 4 }}>
                {isHelpingAllyWar
                  ? "Ти допомагаєш — твої кліки йдуть на баланс союзника. Натисни, щоб зупинити."
                  : "Натисни, щоб допомогти — кліки підуть на баланс союзника замість твого"}
              </div>
              <div className="cn-war-power-row" style={{ marginTop: 8 }}>
                <span>{fmt(allyWar.attackerPower || 0)}</span>
                <div className="cn-war-power-bar">
                  <div
                    className="cn-war-power-fill cn-war-power-fill--attacker"
                    style={{
                      width:
                        ((allyWar.attackerPower || 0) / Math.max(1, (allyWar.attackerPower || 0) + (allyWar.defenderPower || 0))) * 100 +
                        "%",
                    }}
                  />
                </div>
                <span>{fmt(allyWar.defenderPower || 0)}</span>
              </div>
            </>
          )}
        </div>
      )}

      <div className="cn-power-block">
        <div className="cn-power-label">POWER</div>
        <div className="cn-power-value-row">
          <span className="cn-power-dots">····</span>
          <span className="cn-power-value">{fmt(player.power)}</span>
          <span className="cn-power-dots">····</span>
        </div>
      </div>

      <div
        ref={globeRef}
        className={
          "cn-globe-wrap" +
          (pressed ? " cn-globe-wrap--pressed" : "") +
          (shake ? " cn-globe-wrap--shake" : "") +
          (isEmpty ? " cn-globe-wrap--empty" : "")
        }
        onPointerDown={handlePress}
        role="button"
        aria-label="Клікни по глобусу"
      >
        <div className="cn-globe-glow" />
        <svg viewBox="0 0 200 200" className="cn-globe-svg">
          <defs>
            <radialGradient id="globeGrad" cx="35%" cy="28%" r="75%">
              <stop offset="0%" stopColor="#1E5A8E" />
              <stop offset="55%" stopColor="#0B2A4A" />
              <stop offset="100%" stopColor="#040D1C" />
            </radialGradient>
          </defs>
          <circle cx="100" cy="100" r="92" fill="url(#globeGrad)" stroke="#22D3EE" strokeOpacity="0.55" strokeWidth="1.5" />
          <g className="cn-globe-lines">
            <ellipse cx="100" cy="100" rx="92" ry="28" fill="none" stroke="#3FD6E8" strokeOpacity="0.3" strokeWidth="1" />
            <ellipse cx="100" cy="100" rx="92" ry="55" fill="none" stroke="#3FD6E8" strokeOpacity="0.3" strokeWidth="1" />
            <ellipse cx="100" cy="100" rx="28" ry="92" fill="none" stroke="#3FD6E8" strokeOpacity="0.3" strokeWidth="1" />
            <ellipse cx="100" cy="100" rx="55" ry="92" fill="none" stroke="#3FD6E8" strokeOpacity="0.3" strokeWidth="1" />
            <line x1="8" y1="100" x2="192" y2="100" stroke="#3FD6E8" strokeOpacity="0.25" strokeWidth="1" />
          </g>
          <circle cx="100" cy="100" r="92" fill="none" stroke="#22D3EE" strokeOpacity="0.9" strokeWidth="2" className="cn-globe-ring" />
        </svg>
        {effects.map((eft) => (
          <React.Fragment key={eft.id}>
            <span className="cn-ripple" style={{ left: eft.x, top: eft.y }} />
            <span className="cn-particle" style={{ left: eft.x, top: eft.y }}>
              +1
            </span>
          </React.Fragment>
        ))}
      </div>

      <div className="cn-energy-block">
        <div className="cn-energy-pill">
          <Flame size={15} className="cn-energy-icon" />
          <span className="cn-energy-text">
            {Math.floor(energy)} / {MAX_ENERGY}
          </span>
        </div>
        <div className="cn-energy-bar">
          <div className="cn-energy-fill" style={{ width: energyPct + "%" }} />
        </div>
        {isEmpty && <div className="cn-energy-empty-note">Енергія відновлюється +1 щосекунди</div>}
      </div>

      {player.hasPremiumPass && (
        <div className="cn-autoclicker-block">
          <button
            type="button"
            className={"cn-autoclicker-toggle" + (autoClickerActive ? " cn-autoclicker-toggle--on" : "")}
            onClick={toggleAutoClicker}
            disabled={!player.autoClickerOn && autoClickerRemainingMs <= 0}
          >
            <Crown size={14} />
            Автоклікер: {autoClickerActive ? "УВІМКНЕНО" : "вимкнено"}
          </button>
          <div className="cn-autoclicker-hint">
            {autoClickerRemainingMs > 0
              ? `Залишилось на сьогодні: ${fmtDuration(autoClickerRemainingMs)}`
              : "Ліміт на сьогодні вичерпано — повернеться завтра"}
          </div>
        </div>
      )}

      <div className="cn-stats-row">
        <div className="cn-stat-chip">
          <span className="cn-stat-chip-dots">⁚⁚</span>
          <div className="cn-stat-chip-body">
            <span className="cn-stat-chip-label">TOTAL CLICKS</span>
            <span className="cn-stat-chip-value">{fmt(player.totalClicks)}</span>
          </div>
          <span className="cn-stat-chip-dots">⁚⁚</span>
        </div>
      </div>

      <button className="cn-control-toggle" type="button" onClick={() => setPanelOpen((o) => !o)}>
        <Gamepad2 size={16} /> Панель управління
        <ChevronDown size={16} className={"cn-chevron" + (panelOpen ? " cn-chevron--open" : "")} />
      </button>

      {panelOpen && (
        <ControlPanel
          player={player}
          wars={wars}
          rebellions={rebellions}
          alliances={alliances}
          cityControl={cityControl}
          cityDefense={cityDefense}
          isLeader={isLeader}
          isAdvisor={isAdvisor}
          players={players}
          onSetPlayer={onSetPlayer}
          onRefreshGameData={onRefreshGameData}
        />
      )}

      {newsOpen && <NewsModal news={news} onClose={() => setNewsOpen(false)} />}
      {rewardsOpen && <DailyRewardsModal onClose={() => setRewardsOpen(false)} />}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Country shape mini-preview                                          */
/* ------------------------------------------------------------------ */

function CountryShape({ code, size }) {
  const paths = COUNTRY_SVG_PATHS[code];
  const groupRef = useRef(null);
  const [vb, setVb] = useState(null);

  useEffect(() => {
    setVb(null);
    if (!groupRef.current || !paths) return;
    try {
      const bbox = groupRef.current.getBBox();
      const pad = Math.max(bbox.width, bbox.height, 1) * 0.1;
      setVb(`${bbox.x - pad} ${bbox.y - pad} ${bbox.width + pad * 2} ${bbox.height + pad * 2}`);
    } catch {
      /* ignore */
    }
  }, [code, paths]);

  if (!paths) return <Globe2 size={size} className="cn-country-shape-fallback" />;

  return (
    <svg
      viewBox={vb || "0 0 200 200"}
      width={size}
      height={size}
      className="cn-country-shape"
      style={{ opacity: vb ? 1 : 0 }}
    >
      <g ref={groupRef}>
        {paths.map((d, i) => (
          <path key={i} d={d} />
        ))}
      </g>
    </svg>
  );
}

/* ------------------------------------------------------------------ */
/*  Control Panel                                                       */
/* ------------------------------------------------------------------ */

function ControlPanel({ player, wars, rebellions, alliances, cityControl, cityDefense, isLeader, isAdvisor, players, onSetPlayer, onRefreshGameData }) {
  const [group, setGroup] = useState(null);
  const [section, setSection] = useState(null);

  const myWar = useMemo(
    () =>
      (wars || []).find(
        (w) =>
          w.status === "battle" &&
          (w.attackerCountry === player.countryCode ||
            w.defenderCountry === player.countryCode ||
            (w.attackerAllies || []).includes(player.countryCode) ||
            (w.defenderAllies || []).includes(player.countryCode))
      ),
    [wars, player.countryCode]
  );

  const atPeace = !countryAtWar(wars || [], player.countryCode);

  const GROUPS = [
    {
      id: "war",
      label: "Війна",
      icon: Swords,
      items: [
        { id: "attack", label: "Атака", icon: Swords },
        { id: "defense", label: "Захист", icon: Shield },
        { id: "recon", label: "Розвідка", icon: Compass },
        { id: "declareWar", label: "Оголосити війну", icon: Flame },
      ],
    },
    {
      id: "diplomacy",
      label: "Дипломатія",
      icon: Handshake,
      items: [
        { id: "formAlliance", label: "Підписати альянс", icon: Handshake },
        { id: "allyList", label: "Список союзників", icon: Users },
      ],
    },
    {
      id: "country",
      label: "Країна",
      icon: Globe2,
      items: [
        { id: "countryInfo", label: "Інформація про країну", icon: Globe2 },
        { id: "countryLeader", label: "Хто лідер", icon: Crown },
        { id: "countryPlayers", label: "Скільки гравців", icon: Users },
        { id: "countryChart", label: "Графік активності", icon: BarChart3 },
        { id: "countryStats", label: "Детальна статистика", icon: ScrollText },
      ],
    },
    {
      id: "power",
      label: "Влада",
      icon: UserCog,
      items: [
        { id: "council", label: "Рада", icon: UserCog },
        { id: "rebellion", label: "Повстання", icon: Flame },
      ],
    },
  ];

  const activeGroup = GROUPS.find((g) => g.id === group);

  const selectGroup = (id) => {
    if (group === id) {
      setGroup(null);
      setSection(null);
    } else {
      setGroup(id);
      setSection(null);
    }
  };

  return (
    <div className="cn-control-panel">
      <div className="cn-control-header">
        <CountryShape code={player.countryCode} size={72} />
        <div className="cn-control-header-text">
          <div className="cn-control-header-country">
            <Flag code={COUNTRY_MAP[player.countryCode]?.code} size={22} /> {COUNTRY_MAP[player.countryCode]?.name}
          </div>
          <div className="cn-control-header-power">
            Баланс: <span className="cn-control-header-power-value">{fmt(player.power)} Power</span>
          </div>
        </div>
      </div>

      <div className="cn-control-grid">
        {GROUPS.map((g) => {
          const Icon = g.icon;
          return (
            <button
              key={g.id}
              type="button"
              className={"cn-control-btn" + (group === g.id ? " cn-control-btn--active" : "")}
              onClick={() => selectGroup(g.id)}
            >
              <Icon size={30} className="cn-control-btn-icon" />
              <span>{g.label}</span>
            </button>
          );
        })}
      </div>

      {activeGroup && (
        <div className="cn-control-subgrid">
          {activeGroup.items.map((it) => {
            const Icon = it.icon;
            return (
              <button
                key={it.id}
                type="button"
                className={"cn-control-subbtn" + (section === it.id ? " cn-control-subbtn--active" : "")}
                onClick={() => setSection(section === it.id ? null : it.id)}
              >
                <Icon size={20} className="cn-control-btn-icon" />
                <span>{it.label}</span>
              </button>
            );
          })}
        </div>
      )}

      {section === "attack" && (
        <AttackSection player={player} myWar={myWar} onSetPlayer={onSetPlayer} onRefreshGameData={onRefreshGameData} />
      )}
      {section === "defense" && (
        <DefenseSection
          player={player}
          atPeace={atPeace}
          cityDefense={cityDefense}
          cityControl={cityControl}
          onSetPlayer={onSetPlayer}
          onRefreshGameData={onRefreshGameData}
        />
      )}
      {section === "recon" && (
        <ReconSection player={player} isLeader={isLeader} isAdvisor={isAdvisor} cityControl={cityControl} cityDefense={cityDefense} />
      )}
      {section === "declareWar" && (
        <DeclareWarSection
          player={player}
          isLeader={isLeader}
          isAdvisor={isAdvisor}
          wars={wars}
          cityControl={cityControl}
          onSetPlayer={onSetPlayer}
          onRefreshGameData={onRefreshGameData}
        />
      )}
      {section === "formAlliance" && (
        <FormAllianceSection
          player={player}
          isLeader={isLeader}
          isAdvisor={isAdvisor}
          alliances={alliances}
          onRefreshGameData={onRefreshGameData}
        />
      )}
      {section === "allyList" && <DiplomacySection player={player} alliances={alliances} />}
      {section === "council" && (
        <CouncilSection
          player={player}
          isLeader={isLeader}
          isAdvisor={isAdvisor}
          players={players}
          onSetPlayer={onSetPlayer}
          onRefreshGameData={onRefreshGameData}
        />
      )}
      {section === "rebellion" && (
        <RebellionSection
          player={player}
          isLeader={isLeader}
          isAdvisor={isAdvisor}
          rebellions={rebellions}
          players={players}
          onSetPlayer={onSetPlayer}
          onRefreshGameData={onRefreshGameData}
        />
      )}
      {(section === "countryInfo" ||
        section === "countryLeader" ||
        section === "countryPlayers" ||
        section === "countryChart" ||
        section === "countryStats") && (
        <CountrySection
          view={section}
          player={player}
          players={players}
          isLeader={isLeader}
          wars={wars}
        />
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Country section (info / leader / player count / chart / stats)     */
/* ------------------------------------------------------------------ */

function CountrySection({ view, player, players, isLeader, wars }) {
  const list = players || [];
  const country = COUNTRY_MAP[player.countryCode];

  const [leaderInfo, setLeaderInfo] = useState(undefined); // undefined = loading, null = none

  useEffect(() => {
    if (view !== "countryLeader" && view !== "countryInfo") return;
    let cancelled = false;
    setLeaderInfo(undefined);
    (async () => {
      const leaderId = await getLeader(player.countryCode);
      if (cancelled) return;
      if (!leaderId) {
        setLeaderInfo(null);
        return;
      }
      const p = list.find((pl) => pl.id === leaderId);
      setLeaderInfo({ username: p ? p.username : "Гравець" });
    })();
    return () => {
      cancelled = true;
    };
  }, [view, player.countryCode]);

  const worldRanked = useMemo(() => {
    const map = {};
    const counts = {};
    for (const p of list) {
      map[p.countryCode] = (map[p.countryCode] || 0) + (p.power || 0);
      counts[p.countryCode] = (counts[p.countryCode] || 0) + 1;
    }
    return COUNTRIES.map((c) => ({ ...c, power: map[c.code] || 0, playerCount: counts[c.code] || 0 }))
      .sort((a, b) => b.power - a.power)
      .map((c, i) => ({ ...c, rank: i + 1 }));
  }, [list]);

  const myCountryRanked = worldRanked.find((c) => c.code === player.countryCode);

  const globalRank = useMemo(() => {
    const sorted = [...list].sort((a, b) => (b.power || 0) - (a.power || 0));
    const idx = sorted.findIndex((p) => p.id === player.id);
    return idx >= 0 ? idx + 1 : "—";
  }, [list, player.id]);

  const countryRank = useMemo(() => {
    const sorted = list
      .filter((p) => p.countryCode === player.countryCode)
      .sort((a, b) => (b.power || 0) - (a.power || 0));
    const idx = sorted.findIndex((p) => p.id === player.id);
    return idx >= 0 ? idx + 1 : "—";
  }, [list, player.id, player.countryCode]);

  const countryPlayers = useMemo(
    () => list.filter((p) => p.countryCode === player.countryCode).sort((a, b) => (b.power || 0) - (a.power || 0)),
    [list, player.countryCode]
  );

  if (view === "countryInfo") {
    return (
      <div className="cn-control-section">
        <div className="cn-profile-grid">
          <ProfileStat
            label="Країна"
            value={
              <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
                <Flag code={country?.code} size={16} /> {country?.name}
              </span>
            }
          />
          <ProfileStat label="Country Power" value={fmt(myCountryRanked?.power || 0)} />
          <ProfileStat label="Місце у світі" value={myCountryRanked ? "#" + fmt(myCountryRanked.rank) : "—"} />
          <ProfileStat label="Гравців" value={fmt(myCountryRanked?.playerCount || 0)} />
          <ProfileStat label="Лідер" value={leaderInfo === undefined ? "…" : leaderInfo ? leaderInfo.username : "Немає"} />
          <ProfileStat label="Статус" value={roleStatusLabel(isLeader, player.role)} />
        </div>
      </div>
    );
  }

  if (view === "countryLeader") {
    return (
      <div className="cn-control-section">
        {leaderInfo === undefined ? (
          <div className="cn-control-empty">Завантаження…</div>
        ) : leaderInfo ? (
          <div className="cn-control-wip">
            <Crown size={22} />
            <div>
              Лідер {country?.name} — <b>{leaderInfo.username}</b>
              {isLeader && " (це ти)"}
            </div>
          </div>
        ) : (
          <div className="cn-control-empty">У {country?.name} поки немає лідера.</div>
        )}
      </div>
    );
  }

  if (view === "countryPlayers") {
    return (
      <div className="cn-control-section">
        <div className="cn-alliance-section-title">Гравців у {country?.name} ({countryPlayers.length})</div>
        {countryPlayers.length === 0 ? (
          <div className="cn-control-empty">Поки немає даних про гравців.</div>
        ) : (
          <div className="cn-list">
            {countryPlayers.slice(0, 30).map((p) => (
              <div key={p.id} className="cn-row">
                <span className="cn-row-name">{p.username || "Гравець"}</span>
                <span className="cn-region-country-count">{fmt(p.power || 0)} Power</span>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  if (view === "countryChart") {
    const top = countryPlayers.slice(0, 10);
    const maxPower = Math.max(1, ...top.map((p) => p.power || 0));
    return (
      <div className="cn-control-section">
        <div className="cn-alliance-section-title">Найактивніші гравці {country?.name}</div>
        {top.length === 0 ? (
          <div className="cn-control-empty">Поки немає даних для графіка.</div>
        ) : (
          <div style={{ marginTop: 8 }}>
            {top.map((p) => (
              <div key={p.id} className="cn-country-bar-row">
                <span className="cn-country-bar-name">{p.username || "Гравець"}</span>
                <span className="cn-country-bar-track">
                  <span
                    className="cn-country-bar-fill"
                    style={{ width: `${Math.max(4, ((p.power || 0) / maxPower) * 100)}%` }}
                  />
                </span>
                <span className="cn-country-bar-value">{fmt(p.power || 0)}</span>
              </div>
            ))}
            <div className="cn-control-hint">Стовпчики показують Power гравця відносно найсильнішого в країні. Кліки: {fmt(top.reduce((s, p) => s + (p.totalClicks || 0), 0))}</div>
          </div>
        )}
      </div>
    );
  }

  if (view === "countryStats") {
    const accountDays = Math.max(0, Math.floor((Date.now() - (player.createdAt || Date.now())) / 86400000));
    const myWarsCount = (wars || []).filter(
      (w) => w.attackerCountry === player.countryCode || w.defenderCountry === player.countryCode
    ).length;
    const avgPowerPerClick = player.totalClicks > 0 ? (player.power / player.totalClicks).toFixed(2) : "0.00";
    return (
      <div className="cn-control-section">
        <div className="cn-profile-grid">
          <ProfileStat label="Power" value={fmt(player.power)} />
          <ProfileStat label="Total Clicks" value={fmt(player.totalClicks)} />
          <ProfileStat label="Global Rank" value={typeof globalRank === "number" ? "#" + fmt(globalRank) : globalRank} />
          <ProfileStat label="Country Rank" value={typeof countryRank === "number" ? "#" + fmt(countryRank) : countryRank} />
          <ProfileStat label="Power / Click" value={avgPowerPerClick} />
          <ProfileStat label="Днів у грі" value={fmt(accountDays)} />
          <ProfileStat label="Воєн зіграно" value={fmt(myWarsCount)} />
          <ProfileStat label="Статус" value={roleStatusLabel(isLeader, player.role)} />
        </div>
      </div>
    );
  }

  return null;
}

function AttackSection({ player, myWar, onSetPlayer, onRefreshGameData }) {
  const [amount, setAmount] = useState(10);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");

  if (!myWar) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-empty">Немає активної битви за участю твоєї країни просто зараз.</div>
      </div>
    );
  }

  const isAttackerSide =
    myWar.attackerCountry === player.countryCode || (myWar.attackerAllies || []).includes(player.countryCode);
  const sideKey = isAttackerSide ? "attackerPower" : "defenderPower";
  const maxAmount = Math.max(1, player.power);

  const submit = async () => {
    const value = clamp(Math.round(amount), 1, maxAmount);
    setBusy(true);
    const list = await getWars();
    const idx = list.findIndex((w) => w.id === myWar.id);
    if (idx >= 0) {
      list[idx][sideKey] = (list[idx][sideKey] || 0) + value;
      await saveWars(list);
    }
    const updatedPlayer = { ...player, power: player.power - value };
    await storageSet(PLAYER_PREFIX + player.id, JSON.stringify(updatedPlayer), true);
    onSetPlayer(updatedPlayer);
    await onRefreshGameData();
    setMsg(`✓ Внесено ${fmt(value)} Power у битву`);
    setBusy(false);
  };

  return (
    <div className="cn-control-section">
      <div className="cn-war-banner-row" style={{ marginBottom: 6 }}>
        <span className="cn-war-side">
          <Flag code={COUNTRY_MAP[myWar.attackerCountry]?.code} size={16} /> {COUNTRY_MAP[myWar.attackerCountry]?.name}
        </span>
        <Swords size={15} className="cn-war-vs-icon" />
        <span className="cn-war-side">
          <Flag code={COUNTRY_MAP[myWar.defenderCountry]?.code} size={16} /> {COUNTRY_MAP[myWar.defenderCountry]?.name}
        </span>
      </div>
      <div className="cn-war-city">за {myWar.city}</div>
      <div className="cn-war-power-row" style={{ marginTop: 10 }}>
        <span>{fmt(myWar.attackerPower || 0)}</span>
        <div className="cn-war-power-bar">
          <div
            className="cn-war-power-fill cn-war-power-fill--attacker"
            style={{ width: ((myWar.attackerPower || 0) / Math.max(1, (myWar.attackerPower || 0) + (myWar.defenderPower || 0))) * 100 + "%" }}
          />
        </div>
        <span>{fmt(myWar.defenderPower || 0)}</span>
      </div>

      <div className="cn-power-input-row">
        <button type="button" className="cn-map-zoom-btn" onClick={() => setAmount((a) => clamp(a - 10, 1, maxAmount))}>
          <Minus size={14} />
        </button>
        <input
          type="number"
          className="cn-power-input"
          value={amount}
          min={1}
          max={maxAmount}
          onChange={(e) => setAmount(clamp(parseInt(e.target.value || "1", 10), 1, maxAmount))}
        />
        <button type="button" className="cn-map-zoom-btn" onClick={() => setAmount((a) => clamp(a + 10, 1, maxAmount))}>
          <Plus size={14} />
        </button>
      </div>
      <div className="cn-control-hint">Доступно: {fmt(player.power)} Power</div>
      <button className="cn-war-attack-btn" type="button" disabled={busy || player.power < 1} onClick={submit}>
        <Swords size={16} /> Внести Power за {isAttackerSide ? "напад" : "захист"}
      </button>
      {msg && <div className="cn-dev-status-msg" style={{ marginTop: 8 }}>{msg}</div>}
    </div>
  );
}

function DefenseSection({ player, atPeace, cityDefense, cityControl, onSetPlayer, onRefreshGameData }) {
  const [query, setQuery] = useState("");
  const [regionKey, setRegionKey] = useState(null); // "nativeCountryCode|regionName"
  const [amount, setAmount] = useState(10);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");

  /* Regions I currently control: my own native regions (minus any lost to
     someone else) plus any regions I've captured from other countries. */
  const controlledRegions = useMemo(() => {
    const list = [];
    const myNative = getRegionData()[player.countryCode]?.regions || [];
    for (const r of myNative) {
      const owner = cityControl?.[player.countryCode + "|" + r.name];
      if (!owner || owner === player.countryCode) {
        list.push({ key: player.countryCode + "|" + r.name, name: r.name, nativeCountry: player.countryCode, captured: false });
      }
    }
    for (const key in cityControl || {}) {
      if (cityControl[key] !== player.countryCode) continue;
      const sep = key.indexOf("|");
      const nativeCountry = key.slice(0, sep);
      const name = key.slice(sep + 1);
      if (nativeCountry === player.countryCode) continue; // already covered above
      list.push({ key, name, nativeCountry, captured: true });
    }
    return list;
  }, [cityControl, player.countryCode]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return controlledRegions;
    return controlledRegions.filter((r) => r.name.toLowerCase().includes(q));
  }, [controlledRegions, query]);

  const selected = regionKey ? controlledRegions.find((r) => r.key === regionKey) : null;

  if (!atPeace) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-empty">Твоя країна зараз веде війну — зміцнювати захист можна лише в мирний час.</div>
      </div>
    );
  }

  const maxAmount = Math.max(1, player.power);
  const currentStock = selected ? cityDefense?.[selected.key] || 0 : 0;

  const submit = async () => {
    if (!selected) return;
    const value = clamp(Math.round(amount), 1, maxAmount);
    setBusy(true);
    const defense = await getCityDefense();
    defense[selected.key] = (defense[selected.key] || 0) + value;
    await saveCityDefense(defense);
    const updatedPlayer = { ...player, power: player.power - value };
    await storageSet(PLAYER_PREFIX + player.id, JSON.stringify(updatedPlayer), true);
    onSetPlayer(updatedPlayer);
    await onRefreshGameData();
    setMsg(`✓ Захист області «${selected.name}» зміцнено на ${fmt(value)} Power`);
    setBusy(false);
  };

  return (
    <div className="cn-control-section">
      <div className="cn-control-hint" style={{ marginBottom: 8 }}>
        Обери область, яку контролює твоя країна (свою або захоплену), щоб заздалегідь зміцнити її захист. Цей запас додасться до Power оборони, якщо на область нападуть.
      </div>
      {!selected ? (
        <>
          <div className="cn-country-search-wrap">
            <Search size={15} className="cn-country-search-icon" />
            <input className="cn-country-search" placeholder="Пошук області…" value={query} onChange={(e) => setQuery(e.target.value)} />
          </div>
          <div className="cn-region-country-list" style={{ maxHeight: "38vh" }}>
            {filtered.length === 0 && <div className="cn-control-empty">Немає областей під твоїм контролем</div>}
            {filtered.map((r) => (
              <button key={r.key} type="button" className="cn-region-country-row" onClick={() => setRegionKey(r.key)}>
                <span className="cn-region-country-name">
                  {r.name}
                  {r.captured && <span className="cn-region-country-captured-tag">захоплено</span>}
                </span>
                <span className="cn-region-country-count">{fmt(cityDefense?.[r.key] || 0)} Power</span>
              </button>
            ))}
          </div>
        </>
      ) : (
        <>
          <div className="cn-war-city">Область: {selected.name} (поточний запас: {fmt(currentStock)} Power)</div>
          <div className="cn-power-input-row">
            <button type="button" className="cn-map-zoom-btn" onClick={() => setAmount((a) => clamp(a - 10, 1, maxAmount))}>
              <Minus size={14} />
            </button>
            <input
              type="number"
              className="cn-power-input"
              value={amount}
              min={1}
              max={maxAmount}
              onChange={(e) => setAmount(clamp(parseInt(e.target.value || "1", 10), 1, maxAmount))}
            />
            <button type="button" className="cn-map-zoom-btn" onClick={() => setAmount((a) => clamp(a + 10, 1, maxAmount))}>
              <Plus size={14} />
            </button>
          </div>
          <div className="cn-control-hint">Доступно: {fmt(player.power)} Power</div>
          <div style={{ display: "flex", gap: 8 }}>
            <button className="cn-dev-btn" type="button" onClick={() => setRegionKey(null)}>
              Інша область
            </button>
            <button className="cn-war-attack-btn" type="button" disabled={busy || player.power < 1} onClick={submit} style={{ flex: 1 }}>
              <Shield size={16} /> Зміцнити захист
            </button>
          </div>
          {msg && <div className="cn-dev-status-msg" style={{ marginTop: 8 }}>{msg}</div>}
        </>
      )}
    </div>
  );
}

/* Розвідка: доступна лише владі (лідер/радники) своєї країни. Дозволяє
   обрати чужу країну та конкретну область і подивитися, скільки Power
   стоїть там на захисті та хто зараз контролює область. */
function ReconSection({ player, isLeader, isAdvisor, cityControl, cityDefense }) {
  const [countryQuery, setCountryQuery] = useState("");
  const [targetCountry, setTargetCountry] = useState(null);
  const [regionQuery, setRegionQuery] = useState("");
  const [targetRegion, setTargetRegion] = useState(null);

  if (!isLeader && !isAdvisor) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-empty">
          Кнопка «Розвідка» доступна лише владі країни — лідеру або радникам. Купи роль у Магазині за {fmt(ROLE_PRICE)} Power.
        </div>
      </div>
    );
  }

  const filteredCountries = useMemo(() => {
    const q = countryQuery.trim().toLowerCase();
    const list = COUNTRIES.filter((c) => c.code !== player.countryCode);
    if (!q) return list;
    return list.filter((c) => c.name.toLowerCase().includes(q) || c.code.toLowerCase().includes(q));
  }, [countryQuery, player.countryCode]);

  const targetRegions = targetCountry ? getRegionData()[targetCountry]?.regions || [] : [];
  const filteredRegions = useMemo(() => {
    const q = regionQuery.trim().toLowerCase();
    if (!q) return targetRegions;
    return targetRegions.filter((r) => r.name.toLowerCase().includes(q));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [targetRegions, regionQuery]);

  if (!targetCountry) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-hint" style={{ marginBottom: 8 }}>
          <Compass size={14} /> Обери країну, яку хочеш розвідати
        </div>
        <div className="cn-country-search-wrap">
          <Search size={15} className="cn-country-search-icon" />
          <input className="cn-country-search" placeholder="Пошук країни…" value={countryQuery} onChange={(e) => setCountryQuery(e.target.value)} />
        </div>
        <div className="cn-region-country-list" style={{ maxHeight: "38vh" }}>
          {filteredCountries.map((c) => (
            <button key={c.code} type="button" className="cn-region-country-row" onClick={() => setTargetCountry(c.code)}>
              <Flag code={c.code} size={18} className="cn-region-country-flag" />
              <span className="cn-region-country-name">{c.name}</span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  if (!targetRegion) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-hint" style={{ marginBottom: 8 }}>
          Обери конкретну область <Flag code={COUNTRY_MAP[targetCountry]?.code} size={16} /> {COUNTRY_MAP[targetCountry]?.name}
        </div>
        <div className="cn-country-search-wrap">
          <Search size={15} className="cn-country-search-icon" />
          <input className="cn-country-search" placeholder="Пошук області…" value={regionQuery} onChange={(e) => setRegionQuery(e.target.value)} />
        </div>
        <div className="cn-region-country-list" style={{ maxHeight: "34vh" }}>
          {filteredRegions.map((r) => (
            <button key={r.name} type="button" className="cn-region-country-row" onClick={() => setTargetRegion(r.name)}>
              <span className="cn-region-country-name">{r.name}</span>
            </button>
          ))}
        </div>
        <button className="cn-dev-btn" type="button" onClick={() => setTargetCountry(null)}>
          <ArrowLeft size={13} /> Інша країна
        </button>
      </div>
    );
  }

  const owner = cityControl?.[targetCountry + "|" + targetRegion] || targetCountry;
  const defenseKey = owner + "|" + targetRegion;
  const stationedPower = cityDefense?.[defenseKey] || 0;

  return (
    <div className="cn-control-section">
      <div className="cn-war-city">
        <Compass size={15} /> Розвідка: {targetRegion} (<Flag code={COUNTRY_MAP[targetCountry]?.code} size={16} /> {COUNTRY_MAP[targetCountry]?.name})
      </div>
      <div className="cn-control-hint" style={{ marginTop: 8 }}>
        Наразі контролює: <Flag code={COUNTRY_MAP[owner]?.code} size={16} /> {COUNTRY_MAP[owner]?.name}
      </div>
      <div className="cn-control-hint" style={{ marginTop: 4 }}>
        На захисті цієї області: <b>{fmt(stationedPower)} Power</b>
      </div>
      <button className="cn-dev-btn" type="button" onClick={() => setTargetRegion(null)} style={{ marginTop: 10 }}>
        <ArrowLeft size={13} /> Інша область
      </button>
    </div>
  );
}

function DiplomacySection({ player, alliances }) {
  const myAllies = useMemo(
    () =>
      (alliances || [])
        .filter((pair) => pair[0] === player.countryCode || pair[1] === player.countryCode)
        .map((pair) => (pair[0] === player.countryCode ? pair[1] : pair[0]))
        .map((code) => COUNTRY_MAP[code])
        .filter(Boolean),
    [alliances, player.countryCode]
  );

  return (
    <div className="cn-control-section">
      <div className="cn-alliance-section-title">Союзники ({myAllies.length})</div>
      {myAllies.length === 0 ? (
        <div className="cn-control-empty">Поки немає союзників. Скористайся кнопкою «Укласти альянс».</div>
      ) : (
        <div className="cn-list">
          {myAllies.map((c) => (
            <div key={c.code} className="cn-row">
              <Flag code={c.code} size={18} className="cn-row-flag" />
              <span className="cn-row-name">{c.name}</span>
              <Handshake size={16} className="cn-alliance-icon" />
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function DeclareWarSection({ player, isLeader, isAdvisor, wars, cityControl, onSetPlayer, onRefreshGameData }) {
  const [countryQuery, setCountryQuery] = useState("");
  const [targetCountry, setTargetCountry] = useState(null);
  const [cityQuery, setCityQuery] = useState("");
  const [targetCity, setTargetCity] = useState(null);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");
  const [, forceTick] = useState(0);

  useEffect(() => {
    const id = setInterval(() => forceTick((t) => t + 1), 1000);
    return () => clearInterval(id);
  }, []);

  const cooldownLeftMs = isLeader
    ? Math.max(0, ACTION_COOLDOWN_MS - (Date.now() - (player.lastWarDeclareAt || 0)))
    : 0;
  const onCooldown = isLeader && cooldownLeftMs > 0;

  const filteredCountries = useMemo(() => {
    const q = countryQuery.trim().toLowerCase();
    const list = COUNTRIES.filter((c) => c.code !== player.countryCode);
    if (!q) return list;
    return list.filter((c) => c.name.toLowerCase().includes(q) || c.code.toLowerCase().includes(q));
  }, [countryQuery, player.countryCode]);

  const targetRegions = targetCountry ? getRegionData()[targetCountry]?.regions || [] : [];
  const filteredCities = useMemo(() => {
    const q = cityQuery.trim().toLowerCase();
    if (!q) return targetRegions;
    return targetRegions.filter((r) => r.name.toLowerCase().includes(q));
  }, [targetRegions, cityQuery]);

  if (!isLeader && !isAdvisor) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-empty">Лише лідер або радники країни можуть ініціювати війну. Купи роль у Магазині за {fmt(ROLE_PRICE)} Power.</div>
      </div>
    );
  }

  if (countryAtWar(wars || [], player.countryCode)) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-empty">Твоя країна вже веде війну. Дочекайся її завершення, перш ніж оголошувати нову.</div>
      </div>
    );
  }

  if (onCooldown) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-empty">
          Ти нещодавно оголошував(ла) війну. Наступне оголошення можливе через {fmtDuration(cooldownLeftMs)}.
        </div>
      </div>
    );
  }

  const submit = async () => {
    if (!targetCountry || !targetCity) return;
    setBusy(true);
    const owner = cityControl?.[targetCountry + "|" + targetCity] || targetCountry;
    if (isLeader) {
      const result = await declareWarAction(player.countryCode, owner, targetCity);
      if (result.ok) {
        setMsg("✓ Війну оголошено! Підготовка триває 10 хвилин.");
        setTargetCountry(null);
        setTargetCity(null);
        const updated = { ...player, lastWarDeclareAt: Date.now() };
        await storageSet(PLAYER_PREFIX + player.id, JSON.stringify(updated), true);
        if (onSetPlayer) onSetPlayer(updated);
      } else {
        setMsg("✗ " + result.reason);
      }
    } else {
      await createCouncilProposal(player.countryCode, { type: "war", payload: { targetCountry: owner, city: targetCity } }, player.id);
      setMsg("✓ Пропозицію про війну винесено на голосування ради (розділ «Влада → Рада»).");
      setTargetCountry(null);
      setTargetCity(null);
    }
    await onRefreshGameData();
    setBusy(false);
  };

  if (!targetCountry) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-hint" style={{ marginBottom: 8 }}>Обери країну-суперника</div>
        <div className="cn-country-search-wrap">
          <Search size={15} className="cn-country-search-icon" />
          <input className="cn-country-search" placeholder="Пошук країни…" value={countryQuery} onChange={(e) => setCountryQuery(e.target.value)} />
        </div>
        <div className="cn-region-country-list" style={{ maxHeight: "38vh" }}>
          {filteredCountries.map((c) => (
            <button key={c.code} type="button" className="cn-region-country-row" onClick={() => setTargetCountry(c.code)}>
              <Flag code={c.code} size={18} className="cn-region-country-flag" />
              <span className="cn-region-country-name">{c.name}</span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  if (!targetCity) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-hint" style={{ marginBottom: 8 }}>
          Обери місто/область <Flag code={COUNTRY_MAP[targetCountry]?.code} size={16} /> {COUNTRY_MAP[targetCountry]?.name}
        </div>
        <div className="cn-country-search-wrap">
          <Search size={15} className="cn-country-search-icon" />
          <input className="cn-country-search" placeholder="Пошук області…" value={cityQuery} onChange={(e) => setCityQuery(e.target.value)} />
        </div>
        <div className="cn-region-country-list" style={{ maxHeight: "34vh" }}>
          {filteredCities.map((r) => {
            const owner = cityControl?.[targetCountry + "|" + r.name];
            return (
              <button key={r.name} type="button" className="cn-region-country-row" onClick={() => setTargetCity(r.name)}>
                <span className="cn-region-country-name">{r.name}</span>
                {owner && owner !== targetCountry && (
                  <Flag code={COUNTRY_MAP[owner]?.code} size={18} className="cn-region-country-count" />
                )}
              </button>
            );
          })}
        </div>
        <button className="cn-dev-btn" type="button" onClick={() => setTargetCountry(null)}>
          <ArrowLeft size={13} /> Інша країна
        </button>
      </div>
    );
  }

  return (
    <div className="cn-control-section">
      <div className="cn-war-city">
        <Flag code={COUNTRY_MAP[player.countryCode]?.code} size={16} /> {COUNTRY_MAP[player.countryCode]?.name} атакує {targetCity} (
        <Flag code={COUNTRY_MAP[targetCountry]?.code} size={16} /> {COUNTRY_MAP[targetCountry]?.name})
      </div>
      <button className="cn-war-declare-btn" type="button" disabled={busy} onClick={submit}>
        <Swords size={15} /> {isLeader ? "Оголосити війну" : "Запропонувати раді"}
      </button>
      <button className="cn-dev-btn" type="button" onClick={() => setTargetCity(null)} style={{ marginTop: 8 }}>
        <ArrowLeft size={13} /> Інша область
      </button>
      {msg && <div className="cn-dev-status-msg" style={{ marginTop: 8 }}>{msg}</div>}
    </div>
  );
}

function FormAllianceSection({ player, isLeader, isAdvisor, alliances, onRefreshGameData }) {
  const [query, setQuery] = useState("");
  const [busy, setBusy] = useState(null);
  const [msg, setMsg] = useState("");

  const allyCodes = new Set(
    (alliances || [])
      .filter((pair) => pair[0] === player.countryCode || pair[1] === player.countryCode)
      .map((pair) => (pair[0] === player.countryCode ? pair[1] : pair[0]))
  );
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    const list = COUNTRIES.filter((c) => c.code !== player.countryCode && !allyCodes.has(c.code));
    if (!q) return list;
    return list.filter((c) => c.name.toLowerCase().includes(q) || c.code.toLowerCase().includes(q));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [query, player.countryCode]);

  if (!isLeader && !isAdvisor) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-empty">Лише лідер або радники країни можуть ініціювати союз. Купи роль у Магазині за {fmt(ROLE_PRICE)} Power.</div>
      </div>
    );
  }

  const send = async (code) => {
    setBusy(code);
    if (isLeader) {
      const result = await sendAllianceRequestAction(player.countryCode, code);
      setMsg(result.ok ? `✓ Запит надіслано ${COUNTRY_MAP[code]?.name}` : "✗ " + result.reason);
    } else {
      await createCouncilProposal(player.countryCode, { type: "alliance", payload: { targetCountry: code } }, player.id);
      setMsg(`✓ Пропозицію про союз із ${COUNTRY_MAP[code]?.name} винесено на голосування ради (розділ «Влада → Рада»).`);
    }
    await onRefreshGameData();
    setBusy(null);
  };

  return (
    <div className="cn-control-section">
      <div className="cn-country-search-wrap">
        <Search size={15} className="cn-country-search-icon" />
        <input className="cn-country-search" placeholder="Пошук країни…" value={query} onChange={(e) => setQuery(e.target.value)} />
      </div>
      <div className="cn-region-country-list" style={{ maxHeight: "38vh" }}>
        {filtered.map((c) => (
          <button key={c.code} type="button" className="cn-region-country-row" disabled={busy === c.code} onClick={() => send(c.code)}>
            <Flag code={c.code} size={18} className="cn-region-country-flag" />
            <span className="cn-region-country-name">{c.name}</span>
            <Send size={14} />
          </button>
        ))}
      </div>
      {msg && <div className="cn-dev-status-msg" style={{ marginTop: 8 }}>{msg}</div>}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Влада: Рада (список радників + рішення на голосуванні)              */
/* ------------------------------------------------------------------ */

function CouncilSection({ player, isLeader, isAdvisor, players, onSetPlayer, onRefreshGameData }) {
  const [advisors, setAdvisors] = useState([]);
  const [proposals, setProposals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");
  const [, forceTick] = useState(0);

  useEffect(() => {
    const id = setInterval(() => forceTick((t) => t + 1), 1000);
    return () => clearInterval(id);
  }, []);

  const advisorCooldownLeftMs = isAdvisor
    ? Math.max(0, ACTION_COOLDOWN_MS - (Date.now() - (player.lastCouncilActionAt || 0)))
    : 0;
  const advisorOnCooldown = isAdvisor && advisorCooldownLeftMs > 0;

  const markAdvisorActionUsed = async () => {
    if (!isAdvisor || isLeader) return; // ліміт стосується лише дій радника, не лідера
    const updated = { ...player, lastCouncilActionAt: Date.now() };
    await storageSet(PLAYER_PREFIX + player.id, JSON.stringify(updated), true);
    if (onSetPlayer) onSetPlayer(updated);
  };

  const load = useCallback(async () => {
    setLoading(true);
    const [adv, props] = await Promise.all([getAdvisors(player.countryCode), getCouncilProposals(player.countryCode)]);
    setAdvisors(adv);
    setProposals(props);
    setLoading(false);
  }, [player.countryCode]);

  useEffect(() => {
    load();
  }, [load]);

  if (!isLeader && !isAdvisor) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-empty">
          Лише лідер або радники країни мають доступ до Ради. Купи роль радника в Магазині за {fmt(ROLE_PRICE)} Power.
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-empty">Завантаження…</div>
      </div>
    );
  }

  const advisorPlayers = advisors.map((id) => (players || []).find((p) => p.id === id)).filter(Boolean);
  const majority = Math.max(1, Math.floor(advisors.length / 2) + 1);

  const vote = async (proposalId) => {
    setBusy(true);
    const res = await voteCouncilProposal(player.countryCode, proposalId, player.id);
    setMsg(res.ok ? (res.executed ? "✓ Рішення схвалено радою та виконано" : "✓ Голос зараховано") : "✗ " + (res.reason || "Помилка"));
    await load();
    await onRefreshGameData();
    setBusy(false);
  };

  const proposeKickAdvisor = async (target) => {
    if (advisorOnCooldown) return;
    setBusy(true);
    await createCouncilProposal(player.countryCode, { type: "kickAdvisor", payload: { targetPlayerId: target.id, targetName: target.username } }, player.id);
    await markAdvisorActionUsed();
    setMsg("✓ Пропозицію винесено на голосування ради");
    await load();
    setBusy(false);
  };

  const proposeKickLeader = async () => {
    if (advisorOnCooldown) return;
    setBusy(true);
    await createCouncilProposal(player.countryCode, { type: "kickLeader", payload: {} }, player.id);
    await markAdvisorActionUsed();
    setMsg("✓ Пропозицію про усунення лідера винесено на голосування ради");
    await load();
    setBusy(false);
  };

  const kickAdvisorDirect = async (target) => {
    setBusy(true);
    await leaderKickAdvisor(player.countryCode, target.id);
    setMsg(`✓ ${target.username} вигнано з ради`);
    await load();
    setBusy(false);
  };

  return (
    <div className="cn-control-section">
      <div className="cn-control-hint" style={{ marginBottom: 8 }}>
        Рада: {advisors.length}/{MAX_ADVISORS} радників. Для ухвалення рішення потрібна більшість голосів ({majority}).
      </div>

      {proposals.length > 0 && (
        <div style={{ marginBottom: 14 }}>
          <div className="cn-control-hint" style={{ marginBottom: 6 }}>Рішення на голосуванні</div>
          <div className="cn-region-country-list" style={{ maxHeight: "26vh" }}>
            {proposals.map((p) => (
              <div key={p.id} className="cn-region-country-row" style={{ flexDirection: "column", alignItems: "stretch", gap: 6 }}>
                <span className="cn-region-country-name">{describeCouncilProposal(p)}</span>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <span style={{ fontSize: 12, opacity: 0.7 }}>Голосів: {p.votes.length}/{majority}</span>
                  {isAdvisor && !p.votes.includes(player.id) ? (
                    <button className="cn-dev-btn" type="button" disabled={busy} onClick={() => vote(p.id)}>
                      <Check size={13} /> Підтримати
                    </button>
                  ) : (
                    isAdvisor && <span style={{ fontSize: 12, opacity: 0.6 }}>✓ Ти вже підтримав(ла)</span>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="cn-control-hint" style={{ marginBottom: 6 }}>Радники ({advisorPlayers.length})</div>
      <div className="cn-region-country-list" style={{ maxHeight: "30vh" }}>
        {advisorPlayers.length === 0 && <div className="cn-control-empty">У раді ще немає радників</div>}
        {advisorPlayers.map((p) => (
          <div key={p.id} className="cn-region-country-row">
            <span className="cn-region-country-name">{p.username}</span>
            {isLeader && (
              <button className="cn-dev-btn" type="button" disabled={busy} onClick={() => kickAdvisorDirect(p)}>
                <Ban size={13} /> Вигнати
              </button>
            )}
            {isAdvisor && !isLeader && p.id !== player.id && (
              <button className="cn-dev-btn" type="button" disabled={busy || advisorOnCooldown} onClick={() => proposeKickAdvisor(p)}>
                Запропонувати вигнання
              </button>
            )}
          </div>
        ))}
      </div>

      {isAdvisor && !isLeader && (
        <button className="cn-dev-btn" type="button" style={{ marginTop: 10 }} disabled={busy || advisorOnCooldown} onClick={proposeKickLeader}>
          <Crown size={13} /> Запропонувати усунення лідера
        </button>
      )}
      {isAdvisor && !isLeader && advisorOnCooldown && (
        <div className="cn-control-hint" style={{ marginTop: 6 }}>
          Наступну дію ради можна вчинити через {fmtDuration(advisorCooldownLeftMs)}
        </div>
      )}

      {msg && <div className="cn-dev-status-msg" style={{ marginTop: 8 }}>{msg}</div>}
    </div>
  );
}

/* Повстання: Повстанець може підняти повстання проти лідера або одного
   з радників своєї країни. Спочатку 10 хв підготовки, потім година битви,
   у якій будь-хто з громадян може обрати сторону (повстанці чи влада) і
   внести туди свій Power — за схемою, схожою на війну. Якщо в кінці битви
   Power повстанців більший — ціль усувають від влади. */
function RebellionSection({ player, isLeader, isAdvisor, rebellions, players, onSetPlayer, onRefreshGameData }) {
  const [advisors, setAdvisors] = useState([]);
  const [leaderId, setLeaderId] = useState(null);
  const [loadingAdvisors, setLoadingAdvisors] = useState(true);
  const [targetType, setTargetType] = useState(null); // "leader" | "advisor"
  const [targetPlayerId, setTargetPlayerId] = useState(null);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");
  const [side, setSide] = useState("rebel"); // "rebel" | "authority"
  const [amount, setAmount] = useState(10);
  const [, forceTick] = useState(0);

  useEffect(() => {
    (async () => {
      setLoadingAdvisors(true);
      const [list, ldr] = await Promise.all([getAdvisors(player.countryCode), getLeader(player.countryCode)]);
      setAdvisors(list);
      setLeaderId(ldr || null);
      setLoadingAdvisors(false);
    })();
  }, [player.countryCode]);

  useEffect(() => {
    const id = setInterval(() => forceTick((t) => t + 1), 1000);
    return () => clearInterval(id);
  }, []);

  const activeRebellion = (rebellions || []).find(
    (r) => r.countryCode === player.countryCode && r.status !== "ended"
  );

  const advisorPlayers = advisors.map((id) => (players || []).find((p) => p.id === id)).filter(Boolean);

  /* --- Active rebellion: show battle status + let any citizen of this
     country contribute Power to whichever side they choose --- */
  if (activeRebellion) {
    const now = Date.now();
    const maxAmount = Math.max(1, player.power);
    const sideKey = side === "rebel" ? "rebelPower" : "authorityPower";

    const submit = async () => {
      const value = clamp(Math.round(amount), 1, maxAmount);
      setBusy(true);
      const list = await getRebellions();
      const idx = list.findIndex((r) => r.id === activeRebellion.id);
      if (idx >= 0 && list[idx].status === "battle") {
        list[idx][sideKey] = (list[idx][sideKey] || 0) + value;
        await saveRebellions(list);
      }
      const updatedPlayer = { ...player, power: player.power - value };
      await storageSet(PLAYER_PREFIX + player.id, JSON.stringify(updatedPlayer), true);
      onSetPlayer(updatedPlayer);
      await onRefreshGameData();
      setMsg(`✓ Внесено ${fmt(value)} Power за ${side === "rebel" ? "повстанців" : "владу"}`);
      setBusy(false);
    };

    return (
      <div className="cn-control-section">
        <div className="cn-war-banner-row" style={{ marginBottom: 6 }}>
          <span className="cn-war-side">
            <Flame size={15} /> {activeRebellion.rebelName}
          </span>
          <Swords size={15} className="cn-war-vs-icon" />
          <span className="cn-war-side">
            <Crown size={15} />{" "}
            {activeRebellion.targetType === "leader" ? "Лідер" : activeRebellion.targetName || "Радник"}
          </span>
        </div>
        <div className="cn-war-city">Повстання в {COUNTRY_MAP[player.countryCode]?.name}</div>

        {activeRebellion.status === "prep" ? (
          <div className="cn-control-hint" style={{ marginTop: 10 }}>
            Підготовка: {Math.max(0, Math.ceil((activeRebellion.prepEndsAt - now) / 1000))} с
          </div>
        ) : (
          <>
            <div className="cn-control-hint" style={{ marginTop: 10 }}>
              Битва: {Math.max(0, Math.ceil((activeRebellion.battleEndsAt - now) / 1000))} с
            </div>
            <div className="cn-war-power-row" style={{ marginTop: 6 }}>
              <span>{fmt(activeRebellion.rebelPower || 0)}</span>
              <div className="cn-war-power-bar">
                <div
                  className="cn-war-power-fill cn-war-power-fill--attacker"
                  style={{
                    width:
                      ((activeRebellion.rebelPower || 0) /
                        Math.max(1, (activeRebellion.rebelPower || 0) + (activeRebellion.authorityPower || 0))) *
                        100 +
                      "%",
                  }}
                />
              </div>
              <span>{fmt(activeRebellion.authorityPower || 0)}</span>
            </div>

            <div className="cn-control-hint" style={{ marginTop: 10, marginBottom: 4 }}>Обери сторону:</div>
            <div className="cn-control-subgrid" style={{ gridTemplateColumns: "1fr 1fr" }}>
              <button
                type="button"
                className={"cn-control-subbtn" + (side === "rebel" ? " cn-control-subbtn--active" : "")}
                onClick={() => setSide("rebel")}
              >
                <Flame size={18} className="cn-control-btn-icon" />
                <span>Повстанці</span>
              </button>
              <button
                type="button"
                className={"cn-control-subbtn" + (side === "authority" ? " cn-control-subbtn--active" : "")}
                onClick={() => setSide("authority")}
              >
                <ShieldCheck size={18} className="cn-control-btn-icon" />
                <span>Влада</span>
              </button>
            </div>

            <div className="cn-power-input-row" style={{ marginTop: 10 }}>
              <button type="button" className="cn-map-zoom-btn" onClick={() => setAmount((a) => clamp(a - 10, 1, maxAmount))}>
                <Minus size={14} />
              </button>
              <input
                type="number"
                className="cn-power-input"
                value={amount}
                min={1}
                max={maxAmount}
                onChange={(e) => setAmount(clamp(parseInt(e.target.value || "1", 10), 1, maxAmount))}
              />
              <button type="button" className="cn-map-zoom-btn" onClick={() => setAmount((a) => clamp(a + 10, 1, maxAmount))}>
                <Plus size={14} />
              </button>
            </div>
            <div className="cn-control-hint">Доступно: {fmt(player.power)} Power</div>
            <button className="cn-war-attack-btn" type="button" disabled={busy || player.power < 1} onClick={submit}>
              <Swords size={16} /> Внести Power за {side === "rebel" ? "повстанців" : "владу"}
            </button>
          </>
        )}
        {msg && <div className="cn-dev-status-msg" style={{ marginTop: 8 }}>{msg}</div>}
      </div>
    );
  }

  /* --- No active rebellion: only a "rebel" can start one --- */
  if (player.role !== "rebel") {
    return (
      <div className="cn-control-section">
        <div className="cn-control-empty">
          Лише Повстанець може підняти повстання проти лідера чи радника. Купи роль у Магазині за {fmt(ROLE_PRICE)} Power.
        </div>
      </div>
    );
  }

  const rebelCooldownLeftMs = Math.max(0, ACTION_COOLDOWN_MS - (Date.now() - (player.lastRebelActionAt || 0)));
  if (rebelCooldownLeftMs > 0) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-empty">
          Ти нещодавно піднімав(ла) повстання. Наступна спроба можлива через {fmtDuration(rebelCooldownLeftMs)}.
        </div>
      </div>
    );
  }

  if (loadingAdvisors) {
    return (
      <div className="cn-control-section">
        <div className="cn-control-empty">Завантаження…</div>
      </div>
    );
  }

  const submitDeclare = async () => {
    if (!targetType || !targetPlayerId) return;
    setBusy(true);
    const targetName =
      targetType === "leader" ? "лідера" : (advisorPlayers.find((p) => p.id === targetPlayerId)?.username || "радника");
    const result = await declareRebellionAction(
      player.id,
      player.username,
      player.countryCode,
      targetType,
      targetPlayerId,
      targetName
    );
    if (result.ok) {
      setMsg("✓ Повстання оголошено! Підготовка триває 10 хвилин.");
      setTargetType(null);
      setTargetPlayerId(null);
      const updated = { ...player, lastRebelActionAt: Date.now() };
      await storageSet(PLAYER_PREFIX + player.id, JSON.stringify(updated), true);
      if (onSetPlayer) onSetPlayer(updated);
    } else {
      setMsg("✗ " + result.reason);
    }
    await onRefreshGameData();
    setBusy(false);
  };

  return (
    <div className="cn-control-section">
      <div className="cn-control-hint" style={{ marginBottom: 8 }}>
        Обери, проти кого підняти повстання
      </div>
      <div className="cn-region-country-list" style={{ maxHeight: "38vh" }}>
        {leaderId ? (
          <button
            type="button"
            className={"cn-region-country-row" + (targetType === "leader" ? " cn-control-subbtn--active" : "")}
            onClick={() => {
              setTargetType("leader");
              setTargetPlayerId(leaderId);
            }}
          >
            <Crown size={18} className="cn-region-country-flag" />
            <span className="cn-region-country-name">Лідер країни</span>
          </button>
        ) : (
          <div className="cn-control-empty">У країні поки немає лідера</div>
        )}
        {advisorPlayers.length === 0 && (
          <div className="cn-control-empty">У раді поки немає радників</div>
        )}
        {advisorPlayers.map((p) => (
          <button
            key={p.id}
            type="button"
            className={"cn-region-country-row" + (targetPlayerId === p.id ? " cn-control-subbtn--active" : "")}
            onClick={() => {
              setTargetType("advisor");
              setTargetPlayerId(p.id);
            }}
          >
            <UserCog size={18} className="cn-region-country-flag" />
            <span className="cn-region-country-name">{p.username}</span>
          </button>
        ))}
      </div>
      <button className="cn-war-declare-btn" type="button" disabled={busy || !targetPlayerId} onClick={submitDeclare} style={{ marginTop: 10 }}>
        <Flame size={15} /> Підняти повстання
      </button>
      {msg && <div className="cn-dev-status-msg" style={{ marginTop: 8 }}>{msg}</div>}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  News                                                                */
/* ------------------------------------------------------------------ */

function NewsModal({ news, onClose }) {
  const close = () => { cnSfx.modalClose(); onClose(); };
  return (
    <div className="cn-modal-overlay" onClick={close}>
      <div className="cn-modal-sheet" onClick={(e) => e.stopPropagation()}>
        <div className="cn-modal-header">
          <div className="cn-modal-title">
            <Newspaper size={16} /> Світові новини
          </div>
          <button className="cn-icon-btn" type="button" onClick={close} aria-label="Закрити">
            <X size={16} />
          </button>
        </div>
        <div className="cn-news-list">
          {(!news || news.length === 0) && <div className="cn-control-empty">Новин поки немає. Тут з'являтимуться війни, союзи та результати битв.</div>}
          {(news || []).map((n) => (
            <div key={n.id} className="cn-news-item">
              <div className="cn-news-text">{n.text}</div>
              <div className="cn-news-time">{timeAgo(n.ts)}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Daily rewards (WIP)                                                 */
/* ------------------------------------------------------------------ */

function DailyRewardsModal({ onClose }) {
  const days = Array.from({ length: 7 }, (_, i) => i + 1);
  const close = () => { cnSfx.modalClose(); onClose(); };
  return (
    <div className="cn-modal-overlay" onClick={close}>
      <div className="cn-modal-sheet" onClick={(e) => e.stopPropagation()}>
        <div className="cn-modal-header">
          <div className="cn-modal-title">
            <Gift size={16} /> Щоденні нагороди
          </div>
          <button className="cn-icon-btn" type="button" onClick={close} aria-label="Закрити">
            <X size={16} />
          </button>
        </div>
        <div className="cn-rewards-grid">
          {days.map((d) => (
            <div key={d} className="cn-reward-cell">
              <Lock size={16} />
              <span>День {d}</span>
            </div>
          ))}
        </div>
        <div className="cn-control-wip" style={{ marginTop: 10 }}>
          <Gift size={20} />
          <div>Щоденні нагороди в розробці. Скоро зможеш отримувати бонуси щодня за вхід у гру.</div>
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Leaderboard screen                                                  */
/* ------------------------------------------------------------------ */

function LeaderboardScreen({ me, players, loading, onRefresh, lang = "uk" }) {
  const [mode, setMode] = useState("countries"); // countries | global | mycountry

  const countriesRanked = useMemo(() => {
    const map = {};
    for (const p of players) {
      map[p.countryCode] = (map[p.countryCode] || 0) + (p.power || 0);
    }
    return COUNTRIES.map((c) => ({ ...c, power: map[c.code] || 0 })).sort((a, b) => b.power - a.power);
  }, [players]);

  const globalRanked = useMemo(() => {
    return [...players].sort((a, b) => (b.power || 0) - (a.power || 0));
  }, [players]);

  const countryRanked = useMemo(() => {
    return globalRanked.filter((p) => p.countryCode === me.countryCode);
  }, [globalRanked, me.countryCode]);

  return (
    <div className="cn-lb">
      <div className="cn-lb-header">
        <div className="cn-screen-title">{t(lang, "nav_leaderboard")}</div>
        <button className="cn-refresh-btn" onClick={onRefresh} type="button" aria-label="Refresh">
          <RefreshCw size={16} className={loading ? "cn-spin" : ""} />
        </button>
      </div>

      <div className="cn-segmented">
        <button
          className={"cn-seg-btn" + (mode === "countries" ? " cn-seg-btn--active" : "")}
          onClick={() => setMode("countries")}
        >
          {t(lang, "lb_countries")}
        </button>
        <button
          className={"cn-seg-btn" + (mode === "global" ? " cn-seg-btn--active" : "")}
          onClick={() => setMode("global")}
        >
          {t(lang, "lb_players")}
        </button>
        <button
          className={"cn-seg-btn" + (mode === "mycountry" ? " cn-seg-btn--active" : "")}
          onClick={() => setMode("mycountry")}
        >
          {t(lang, "lb_mycountry")}
        </button>
      </div>

      {loading && players.length === 0 ? (
        <div className="cn-lb-loading">{t(lang, "lb_loading")}</div>
      ) : mode === "countries" ? (
        <CountryList list={countriesRanked} myCountry={me.countryCode} />
      ) : mode === "global" ? (
        <PlayerList list={globalRanked} meId={me.id} lang={lang} />
      ) : (
        <PlayerList list={countryRanked} meId={me.id} lang={lang} />
      )}
    </div>
  );
}

function rankClass(rank) {
  if (rank === 1) return " cn-rank--1";
  if (rank === 2) return " cn-rank--2";
  if (rank === 3) return " cn-rank--3";
  return "";
}

function CountryList({ list, myCountry }) {
  return (
    <div className="cn-list cn-list--dense">
      {list.map((c, i) => {
        const rank = i + 1;
        const isMine = c.code === myCountry;
        return (
          <div key={c.code} className={"cn-row cn-row--light" + (isMine ? " cn-row--mine" : "")}>
            <span className={"cn-row-rank" + rankClass(rank)}>{rank}</span>
            <Flag code={c.code} size={20} className="cn-row-flag" />
            <span className="cn-row-name">{c.name}</span>
            <span className="cn-row-value">{fmt(c.power)}</span>
          </div>
        );
      })}
    </div>
  );
}

function LbAvatar({ player }) {
  const icon = iconById(player.equippedIcon);
  const premium = !!player.hasPremiumPass;
  return (
    <span className={"cn-lb-avatar" + (premium ? " cn-lb-avatar--premium" : "")}>
      <span className="cn-lb-avatar-inner">
        {icon ? <ProfileIconGlyph opt={icon} size={30} /> : <User size={16} />}
      </span>
      {premium && <Crown size={11} className="cn-lb-avatar-crown" />}
    </span>
  );
}

function PlayerRow({ p, rank, isMine, country }) {
  return (
    <div className={"cn-row cn-row--player" + (isMine ? " cn-row--mine" : "") + (p.hasPremiumPass ? " cn-row--premium" : "")}>
      <span className={"cn-row-rank" + rankClass(rank)}>{rank}</span>
      <LbAvatar player={p} />
      <Flag code={country?.code} size={16} className="cn-row-flag" />
      <span className="cn-row-name">{p.username}</span>
      <span className="cn-row-value">{fmt(p.power)}</span>
    </div>
  );
}

function PlayerList({ list, meId, lang = "uk" }) {
  const TOP_N = 30;
  const myIndex = list.findIndex((p) => p.id === meId);
  const top = list.slice(0, TOP_N);
  const meInTop = myIndex >= 0 && myIndex < TOP_N;
  const mePlayer = myIndex >= 0 ? list[myIndex] : null;

  if (list.length === 0) {
    return <div className="cn-lb-empty">{t(lang, "lb_empty")}</div>;
  }

  return (
    <div className="cn-list">
      {top.map((p, i) => {
        const rank = i + 1;
        const isMine = p.id === meId;
        const country = COUNTRY_MAP[p.countryCode];
        return <PlayerRow key={p.id} p={p} rank={rank} isMine={isMine} country={country} />;
      })}
      {!meInTop && mePlayer && (
        <>
          <div className="cn-row-divider">•••</div>
          <PlayerRow
            p={mePlayer}
            rank={myIndex + 1}
            isMine
            country={COUNTRY_MAP[mePlayer.countryCode]}
          />
        </>
      )}
    </div>
  );
}

